import json, html, pathlib, shutil
root=pathlib.Path(__file__).parent; out=root/'dist'; projects=json.loads((root/'projects.json').read_text()); profile=json.loads((root/'content.json').read_text())['profile']; esc=html.escape
origin='https://zayon-brand-design-portfolio.zayoncreatives.chatgpt.site'
featured=['antelope-constructions','savory-studios','fury-energy-drink','foot-impact','cool-harvest-farms','christian-creator-lab','zara-foods','pillar-academy','unlock-moment','planters','foot-impact-social','kadaba-property-campaigns']
priority={s:i for i,s in enumerate(featured)};order={'identity':0,'packaging':1,'social':2,'graphic':3,'web':4}
projects.sort(key=lambda p:(0,priority[p['slug']]) if p['slug'] in priority else (1,order.get(p['category'],9),p['name'].casefold()))
by_slug={p['slug']:p for p in projects};selected=[by_slug[s] for s in featured]
intro={
'antelope-constructions':'A confident construction identity, built to work from the boardroom to the building site.',
'savory-studios':'A beauty identity with a consistent signature across fragrance, retail and everyday brand touchpoints.',
'fury-energy-drink':'High contrast beverage packaging with a bold typographic presence.',
'foot-impact':'A community identity that connects digital communication, reports and the materials people use in the field.',
'cool-harvest-farms':'A recognisable food packaging family that brings clarity and consistency to a varied product range.',
'christian-creator-lab':'A restrained identity system that brings learning materials, merchandise and digital screens together.',
'zara-foods':'One clear brand language across a range of rice and flour products.',
'pillar-academy':'An academy identity connecting learning interfaces with certificates and physical brand materials.',
'unlock-moment':'A compact visual identity designed to carry across merchandise, signage and promotional media.',
'planters':'A distinctive red graphic language carried through team materials, signage and a vehicle.',
'foot-impact-social':'A consistent visual voice for community awareness, support messages and social content.',
'kadaba-property-campaigns':'Property communication with a clear hierarchy across listings and recurring campaigns.'}
def summary(p):return intro.get(p['slug'],p.get('descriptor',p.get('intro','')))
def img(p,cls='',eager=False):
 g=p.get('gallery',[{}])[0]; ss=g.get('srcSet','');return f'<img class="{cls}" src="{p["image"]}"'+(f' srcset="{ss}" sizes="(max-width: 640px) 90vw, (max-width: 1000px) 45vw, 55vw"' if ss else '')+f' alt="{esc(g.get("alt",p["name"]))}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def card(p,i=0):return f'<a class="project reveal" data-category="{p["category"]}" data-name="{esc(p["name"].lower())}" href="/work/{p["slug"]}/"><div class="project-art">{img(p)}<span class="view">Explore project ↗</span></div><div class="project-meta"><span class="label">{esc(p["type"])}</span><h3>{esc(p["name"])} <span>↗</span></h3><p>{esc(summary(p))}</p></div></a>'
def write(path,title,body,active='',description=None,preview=None):
 target=out/path/'index.html';target.parent.mkdir(parents=True,exist_ok=True)
 canonical=origin+('/' if str(path)=='.' else '/'+str(path).strip('/')+'/')
 desc=description or 'Odusina Isaac is a brand and visual designer based in Nigeria, open to projects worldwide. Explore brand identity, packaging and campaign design.'
 nav=''.join(f'<a {"aria-current=page" if active==n.lower() else ""} href="{u}">{n}</a>' for n,u in [('Work','/work/'),('About','/about/'),('Contact','/contact/')])
 schema={'@context':'https://schema.org','@type':'Person','name':'Odusina Isaac Imoleayo','alternateName':'Odusina Isaac','jobTitle':'Brand and visual designer','url':origin,'image':origin+'/isaac-portrait.webp','sameAs':[profile['behance'],profile['linkedin'],profile['x']]}
 target.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Odusina Isaac</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#f5f5f5"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="icon" href="/personal-icon.svg"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{esc(title)} | Odusina Isaac"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{origin}{preview or '/isaac-portrait.webp'}"><meta name="twitter:card" content="summary_large_image"><link rel="preload" href="/fonts/dm-sans-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/style.css"><script src="/script.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="logo" href="/" aria-label="Odusina Isaac portfolio home">odusina isaac<span>®</span></a><nav aria-label="Main navigation">{nav}</nav><a class="header-cta" href="/contact/">Let’s talk ↗</a></header><main id="main">{body}</main><footer><div class="footer-top"><p class="label">AVAILABLE FOR PROJECTS & CREATIVE COLLABORATIONS</p><a href="/contact/" class="footer-title">Your next chapter.<br>Let’s give it an identity.<span>↗</span></a><p>Brand identity. Packaging. Visual communication.<br>Based in Nigeria. Open to working worldwide.</p></div><div class="footer-links"><a href="mailto:{profile['email']}">{profile['email']} ↗</a><div><a href="{profile['behance']}" target="_blank" rel="noopener">Behance ↗</a><a href="{profile['linkedin']}" target="_blank" rel="noopener">LinkedIn ↗</a><a href="{profile['whatsapp']}" target="_blank" rel="noopener">WhatsApp ↗</a></div></div><div class="footer-bottom"><span>© 2026 Odusina Isaac</span><span>Designed & built by Odusina Isaac</span><a href="#" aria-label="Back to top">Back to top ↑</a></div></footer><dialog id="lightbox"><button aria-label="Close image" class="lightbox-close">Close ×</button><img alt=""><p></p></dialog></body></html>''')
def tools(ps):
 labels=[('All work','all'),('Brand identity','identity'),('Packaging','packaging'),('Campaigns','social'),('Graphic design','graphic')]
 return '<aside class="archive-tools"><p class="label">EXPLORE BY DISCIPLINE</p><div role="group" aria-label="Filter projects">'+''.join(f'<button data-filter="{v}" aria-pressed="{"true" if v=="all" else "false"}"><span>{n}</span><small>{len(ps) if v=="all" else sum(p["category"]==v for p in ps):02}</small></button>' for n,v in labels if v=='all' or any(p['category']==v for p in ps))+'</div><label class="search">Find a project<input id="search" type="search" placeholder="Search by name"></label><label class="sort-label">Project order<select id="sort"><option value="featured">Curated order</option><option value="az">Name: A to Z</option><option value="za">Name: Z to A</option></select></label><p class="filter-note">Identity systems and product ranges lead the collection.</p></aside>'
hero_cards=''.join(f'<a class="hero-card" href="/work/{p["slug"]}/">{img(p,eager=i==0)}<div><p class="label">{esc(p["type"])}</p><h3>{esc(p["name"])} <span>↗</span></h3></div></a>' for i,p in enumerate(selected[:3]))
write(pathlib.Path(''),'Brand identity & packaging designer',f'''<section class="hero"><div class="hero-heading"><div><p class="label">ODUSINA ISAAC / INDEPENDENT DESIGNER</p><h1>Distinct brands.<br>Considered design.</h1></div><div class="hero-intro"><p>I’m a brand and visual designer. I translate what makes a business different into identities, packaging and communication people can recognise.</p><div class="hero-actions"><a class="button" href="#selected">Explore my work ↓</a><a class="text-link" href="/contact/">Discuss a project ↗</a></div><p class="availability"><i></i> Based in Nigeria. Available worldwide.</p></div></div><div class="hero-slider" aria-label="Featured projects">{hero_cards}</div><div class="hero-caption"><span>SELECTED BRAND & PACKAGING PROJECTS</span><a href="/work/">View the complete portfolio ↗</a></div></section><section class="section selected" id="selected"><div class="section-heading"><div><p class="label">THE WORK / A CURATED FIRST LOOK</p><h2>Different businesses.<br>Distinct expressions.</h2></div><p>Start with complete identity systems and product ranges. Each project opens into its design direction, applications and full gallery.</p></div><div class="archive-layout archive">{tools(selected)}<div><p id="result-count" class="label" aria-live="polite">{len(selected)} SELECTED PROJECTS</p><div class="project-grid">{''.join(card(p,i) for i,p in enumerate(selected))}</div><p id="empty" hidden>No projects match. Try another name or discipline.</p><a class="button archive-more" href="/work/">Explore all {len(projects)} projects ↗</a></div></div></section><section class="section about-home" id="about"><div class="about-photo"><img src="/isaac-portrait.webp" alt="Odusina Isaac, brand and visual designer" loading="lazy"><div><p class="label">THE DESIGNER BEHIND THE WORK</p><h3>Odusina Isaac.</h3><p>Brand & visual designer</p></div></div><div class="about-content"><article class="glass philosophy"><p class="label">MY POINT OF VIEW</p><h2>A brand should feel<br>like itself. Everywhere.</h2><p>I look for the idea that makes a business recognisable, then build the visual language around it. The aim is a clear identity that works as confidently on a product or storefront as it does on a screen.</p><a class="text-link" href="/about/">More about my approach ↗</a></article><div class="capability-grid"><article class="glass"><p class="label">01 / IDENTITY</p><h3>From a mark<br>to a visual system.</h3><p>Logo design, typography, colour and brand applications that belong together.</p></article><article class="glass"><p class="label">02 / PACKAGING & COMMUNICATION</p><h3>Designed to be seen.<br>Built to be used.</h3><p>Product ranges, campaigns and digital layouts with a clear reading order and consistent visual voice.</p></article></div></div></section><section class="section collaboration"><p class="label">FOR FOUNDERS, BUSINESSES & CREATIVE TEAMS</p><h2>A new brand. A new range.<br>A fresh perspective.</h2><div><p>I’m open to brand identity and packaging projects, campaign design and creative collaboration. Tell me what you’re building, who it’s for and where you want to take it.</p><a class="button" href="/contact/">Let’s talk about your project ↗</a></div></section>''',preview=selected[0]['image'])
write(pathlib.Path('work'),'Brand identity, packaging & campaign portfolio',f'''<section class="page-head section"><p class="label">THE COMPLETE PORTFOLIO / {len(projects)} PROJECTS</p><h1>See the thinking.<br>Explore the details.</h1><p class="page-description">Complete brand identities first. Packaging and product ranges next. Campaigns and individual graphics follow. Filter by discipline or search for a project.</p></section><section class="section archive"><div class="archive-layout">{tools(projects)}<div><p id="result-count" class="label" aria-live="polite">{len(projects)} PROJECTS</p><div class="project-grid">{''.join(card(p,i) for i,p in enumerate(projects))}</div><p id="empty" hidden>No projects match your search. Try another name or discipline.</p></div></div></section>''','work',preview=selected[0]['image'])
for i,p in enumerate(projects):
 gallery=''.join(f'<figure class="gallery-figure reveal"><button class="image-open" data-caption="{esc(g.get("caption",p["name"]))}" aria-label="Enlarge {esc(g.get("alt",p["name"]))}"><img src="{g["image"]}" alt="{esc(g.get("alt",p["name"]))}" loading="{"eager" if j==0 else "lazy"}" width="{g.get("width",1360)}" height="{g.get("height",767)}"></button><figcaption><span>{j+1:02} / {len(p["gallery"]):02}</span>{esc(g.get('caption',p['name']))}</figcaption></figure>' for j,g in enumerate(p['gallery']))
 story=[]
 for a,b in p.get('story',[]):
  b=str(b).replace('supplied presentations','design presentations').replace('supplied product presentations','product presentations').replace('supplied collection','project').replace('supplied presentations','presentations').replace('The original board is available through the source link below.','').replace('in the complete gallery below.','in the gallery.').replace('Zayon Creative Studios’ social and graphic design archive','my social and graphic design portfolio')
  story.append(f'<article><p class="label">{esc(str(a))}</p><p>{esc(b.strip())}</p></article>')
 nxt=projects[(i+1)%len(projects)]
 write(pathlib.Path('work')/p['slug'],p['name']+' / '+p['type'],f'''<section class="case-head section"><a class="text-link" href="/work/">← All work</a><div class="case-title"><p class="label">{esc(p['type']).upper()} / PORTFOLIO PROJECT</p><h1>{esc(p['name'])}</h1><p class="case-intro">{esc(summary(p))}</p></div><div class="case-info"><span>DESIGNER / ODUSINA ISAAC</span><span>DISCIPLINE / {esc(p['type']).upper()}</span><a href="#gallery">VIEW THE PROJECT GALLERY ↓</a></div></section>{'<section class="case-story section">'+''.join(story)+'</section>' if story else ''}<section class="case-gallery" id="gallery">{gallery}</section><section class="next-project section"><p class="label">CONTINUE EXPLORING</p><a href="/work/{nxt['slug']}/"><h2>{esc(nxt['name'])} ↗</h2>{img(nxt)}</a></section>''','work',description=summary(p)+' Explore the design direction and project gallery by Odusina Isaac.',preview=p['image'])
write(pathlib.Path('about'),'About the designer',f'''<section class="page-head section"><p class="label">ABOUT / ODUSINA ISAAC IMOLEAYO</p><h1>Clear thinking.<br>A distinct point of view.</h1></section><section class="studio-grid section"><div class="about-photo"><img class="portrait" src="/isaac-portrait.webp" alt="Odusina Isaac Imoleayo, brand and visual designer"><div><p class="label">BASED IN NIGERIA / OPEN TO WORK WORLDWIDE</p><h3>Odusina Isaac.</h3></div></div><div class="studio-copy glass"><h2>Making the difference<br>visible.</h2><p>I’m Odusina Isaac Imoleayo, a brand and visual designer working across identity, packaging, campaigns and digital design.</p><p>My work starts with a question: what makes this business different? I use that understanding to develop a visual identity that feels specific to the brand and consistent across the things people see, hold and use.</p><p>This portfolio brings together identity systems for construction, beauty, education and community organisations, alongside food and beverage packaging and campaign communication.</p><p>I’m open to working with founders, businesses and creative teams worldwide, from a focused design brief to a connected set of brand applications.</p><a class="button" href="/contact/">Discuss a project ↗</a></div></section><section class="process section"><p class="label">HOW I WORK</p><h2>Good questions first.<br>Every detail follows.</h2><div class="process-grid">{''.join(f'<article class="glass"><span class="label">0{i+1}</span><h3>{n}</h3><p>{d}</p></article>' for i,(n,d) in enumerate([('Understand','We discuss the business, audience and priorities, then agree on the scope and deliverables.'),('Explore','I develop a visual direction around a clear idea and the character of the brand.'),('Refine','I work through feedback and connect the identity with its intended applications.'),('Deliver','I prepare the agreed artwork and guidance so the design can be used consistently.')]))}</div></section>''','about')
write(pathlib.Path('contact'),'Discuss a design project',f'''<section class="page-head section"><p class="label">NEW PROJECTS / CREATIVE COLLABORATION</p><h1>What are you<br>building next?</h1></section><section class="contact-grid section"><div><h2>Let’s make the<br>next step clear.</h2><p>Tell me about your business, the design you need and the people you want to reach. We can discuss the scope, timing and next steps.</p><a class="contact-email" href="mailto:{profile['email']}">{profile['email']} ↗</a><a href="tel:{profile['telephone']}">{profile['phone']} ↗</a><p class="label">BASED IN NIGERIA / AVAILABLE WORLDWIDE</p><a class="text-link" href="{profile['linkedin']}" target="_blank" rel="noopener">Connect on LinkedIn ↗</a></div><form id="brief" class="glass"><label>Your name<input name="name" autocomplete="name" required placeholder="Your name"></label><label>Business or brand<input name="brand" autocomplete="organization" required placeholder="Your brand name"></label><label>What do you need?<select name="service"><option>Brand identity</option><option>Packaging design</option><option>Campaign and social design</option><option>Website design</option><option>A combination of services</option></select></label><div class="form-pair"><label>Budget range<input name="budget" placeholder="Amount and currency"></label><label>Ideal timeline<input name="timeline" placeholder="Your intended launch date"></label></div><label>A little about your project<textarea name="message" rows="4" required placeholder="What are you building? Who is it for? What would you like the design to achieve?"></textarea></label><button class="submit" type="submit">Prepare WhatsApp brief <span>↗</span></button><p class="form-note">Your brief opens in WhatsApp for you to review and send. Prefer email? Use the email link to get in touch directly.</p></form></section>''','contact')
# Keep the old About URL working, with the same canonical destination.
(out/'studio').mkdir(exist_ok=True);shutil.copyfile(out/'about/index.html',out/'studio/index.html')
(out/'personal-icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#151515"/><text x="32" y="43" text-anchor="middle" fill="white" font-family="sans-serif" font-size="31" font-weight="bold">oi</text></svg>')
(out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+origin+'/sitemap.xml\n')
urls=[origin+'/']+[origin+'/'+route+'/' for route in ['work','about','contact']]+[origin+'/work/'+p['slug']+'/' for p in projects]
(out/'sitemap.xml').write_text('<?xml version="1.0"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in urls)+'</urlset>')
print(f'Built {len(projects)} project pages; {sum(len(p["gallery"]) for p in projects)} retained gallery images.')
